UPDATE lpm_time_assumptions SET statement = 'The hours of a stage are the Zeitrichtwerte of the Sachsen topics that cover it, split over the stages a topic relates to in proportion to the concepts they share and scaled by the share of the topic''s tagged concepts that this space holds.', assumption_type = 'derived', confidence = 'low', source = 'deutsche_lp land/sachsen/lp/data/per-space-tagging, stage-topic relations of 2026-10-25.', rationale = 'The rule is arbitrary. The weights (primary 1, reinforcing 0.4) and the thresholds for covers and partly covers were also run at reinforcing 0.2 and 0.6, and the number of stages with a real topic moved by one at most.', updated_at = NOW() WHERE id = '9a6d0aad-e33e-57f2-b13a-3326b0648efd';
UPDATE lpm_time_assumptions SET statement = 'The relation between a stage and a topic comes from concept tags made by AI on both sides and not audited by a person. Each topic was tagged against the own concepts and definitions of the space, so a concept that two spaces define differently is judged in the sense of each space.', assumption_type = 'derived', confidence = 'low', source = 'Two independent AI passes per space tagged the topics. They made the same tags on 60 to 75 percent of the distinct tags, depending on the space. The stage tags come from the space authors.', rationale = 'A stage with no real topic can be a real gap or a limit of the vocabulary of that space. A sample audit by the team decides which.', updated_at = NOW() WHERE id = '7de280e6-1007-5575-b09b-419711bf4cff';
UPDATE lpm_time_assumptions SET statement = 'Grades 1 to 4 are Sachunterricht topics, grades 5 to 10 are Gymnasium topics of Biologie, Informatik, Technik/Computer, Gemeinschaftskunde, Geschichte, Geographie and Ethik. Grades 11 and 12, the Oberschule and other subjects are not in the data.', assumption_type = 'derived', confidence = 'high', source = 'deutsche_lp land/sachsen/lp/data.', rationale = 'The stages of the 9-12 band can only find grade 9 and 10 topics, so they look earlier than their band.', updated_at = NOW() WHERE id = '9498dfd9-c8d5-52af-bf61-3885dcf42d9a';
UPDATE lpm_time_assumptions SET statement = 'A guidance hour is one Unterrichtsstunde of 45 minutes, and a Zeitrichtwert is a guidance value for a topic and differs from the time a class actually spends on it.', assumption_type = 'literature', confidence = 'high', source = 'Sachsen Lehrpläne and VwV Stundentafeln.', rationale = 'The Lehrpläne plan with 25 of about 39 weeks. The hours here fall inside that plan.', updated_at = NOW() WHERE id = 'd45fcd95-b276-58e3-bf01-3af3c5e2d041';

